//! ⚖️ Canonical error receipt debit preserves both original owner causes without local heap births.
use super::*;
use super::original_output_tests::Lane;
use semio_framework_actor::ActorGuestPhase;
fn clock()->Option<u64>{Some(100)}
fn observer<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);(value,(heap.requested_bytes,heap.released_bytes))}
#[test]
fn original_guest_failure_debit_conserves_external_child_receipts_and_original_cause_pointers(){
 let inputs:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/📥️inputs.json")).unwrap();let expected:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/📤️expected.json")).unwrap();let closing:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🎟️grants.json")).unwrap();let close:RetainedCloneGrant=serde_json::from_value(closing["close"].clone()).unwrap();let denied:RetainedCloneGrant=serde_json::from_value(closing["denied"].clone()).unwrap();
 for(index,input)in inputs.as_array().unwrap().iter().enumerate(){let policy:RetainedCloneGrant=serde_json::from_value(input["grant"].clone()).unwrap();let mut recipient:RetainedCloneProgress=serde_json::from_value(input["recipient"].clone()).unwrap();let child:RetainedCloneProgress=serde_json::from_value(input["originalReceipt"].clone()).unwrap();let received:RetainedCloneProgress=serde_json::from_value(expected[index]["recipient"].clone()).unwrap();let fuel=input["fuel"].as_u64().unwrap();let mut sequence=0;let token=semio_framework_job::root_cancel_token();let mut cx=StepContext::new(semio_framework_job::OperationId(71),semio_framework_job::Generation(3),StepBudget::new(fuel,u64::MAX,policy),token,semio_framework_job::logical_now_us,&mut sequence,&mut recipient);let mut lane=Lane::new(1<<20);let ready_policy=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:128,maximum_capacity_bytes:1048576,maximum_release_bytes:1048576,maximum_depth:128};loop{let input=lane.checkout(ready_policy);let budget=lane.budget(input);let(call,system)=observer(||lane.entry.admit_step(input,budget,clock));let ready=call.result.unwrap().ready;lane.receive(input,call.receipt_spent,call.work_units_spent,system,if ready{ActorGuestPhase::Ready}else{ActorGuestPhase::Pending});if ready{break}}let(cause,heap)=observer(||ValueError::new(ValueRefusalKind::AllocationFailed,"whole original child cause 世界").with_retained_progress(child));let pointer=cause.message.as_ptr();
  let(accepted,observed)=observer(||OriginalActorGuestEntry::debit_original_error(cause,&mut lane.entry.close_fault,&mut cx));assert_eq!(observed,(0,0));assert_eq!(accepted,expected[index]["accepted"].as_bool().unwrap());assert_eq!(cx.retained_progress(),received);assert_eq!(cx.fuel_remaining(),expected[index]["fuel"].as_u64().unwrap());assert_eq!(lane.entry.original_close_fault().unwrap().message.as_ptr(),pointer);assert_eq!(lane.entry.original_close_fault().unwrap().retained_progress(),child);if !accepted{let debit=lane.entry.original_debit_fault().unwrap();assert_eq!(debit.kind,ValueRefusalKind::InvariantViolated);assert_eq!(debit.retained_progress(),child);assert!(matches!(debit.message,std::borrow::Cow::Borrowed(_)));}else{assert!(lane.entry.original_debit_fault().is_none());}let close_turn=|lane:&mut Lane,grant:RetainedCloneGrant|->Option<RetainedCloneProgress>{let input=lane.host.checkout_guest(grant).unwrap()?;let budget=lane.budget(input);let(call,system)=observer(||lane.entry.close_step(input,budget));let spent=call.receipt_spent;assert!(call.result.is_ok());assert!(spent.fits(grant));lane.receive(input,spent,call.work_units_spent,system,ActorGuestPhase::Dispatched);Some(spent)};
  if let Some(spent)=close_turn(&mut lane,denied){assert_eq!(spent,RetainedCloneProgress::default())}assert_eq!(lane.entry.original_close_fault().unwrap().message.as_ptr(),pointer);
  for _ in 0..4096{if lane.entry.terminal_is_empty(){break}let grant=if lane.entry.has_close_causes(){close}else{let demand=lane.entry.context.retirement_demands(close.maximum_copy_bytes).unwrap();RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth.max(1)}};close_turn(&mut lane,grant).expect("original close grant admits");}
  assert!(lane.entry.terminal_is_empty());assert_eq!(lane.capacity+heap.0,lane.released+heap.1);let(original_input,system)=observer(||lane.host.take_dispatched_input().unwrap().unwrap());assert!(original_input.is_empty());assert_eq!(system,(0,0));drop(original_input);let Lane{entry,host,..}=lane;assert_eq!(observer(||drop(entry)).1,(0,0));assert_eq!(observer(||drop(host)).1,(0,0));
 }
}
